#!/usr/bin/env python3
"""Independent parent source-build of exact raw class cap25 profile."""
from pathlib import Path
import hashlib,json,os,re,shutil,subprocess,sys
here=Path(__file__).resolve().parent;root=here.parents[3];cand=here.parent/'classcount25-preflight'
out=Path(sys.argv[1]).resolve();assert out.parent==root/'build' and out.name.startswith('java-diff-mc-classcount25-parent-') and not out.exists();out.mkdir();(out/'tmp').mkdir();(out/'bootstrap-classes').mkdir();env=dict(os.environ,TMPDIR=str(out/'tmp'),NODE_PATH=str(root/'jvmevm/runtime/node_modules'),PYTHONDONTWRITEBYTECODE='1')
def run(label,args,check=True):
 with (out/(label+'.log')).open('w') as f:p=subprocess.run(list(map(str,args)),cwd=root,env=env,stdout=f,stderr=subprocess.STDOUT)
 if check:assert p.returncode==0,(label,p.returncode)
 return p.returncode
# Rebuild existing platform images to prove the count-only engine did not alter them.
names=('String','System','Class','Number','NumberFormatException','Integer');api=out/'rt-without-replaced.jar';shutil.copyfile('/usr/lib/jvm/java-8-openjdk/jre/lib/rt.jar',api);run('strip-platform',['zip','-q','-d',api,*['java/lang/'+n+'.class' for n in names]]);run('java8-build',['/usr/lib/jvm/java-8-openjdk/bin/javac','-source','8','-target','8','-g:none','-bootclasspath',api,'-d',out/'bootstrap-classes',*[here/'bootstrap/java/lang'/(n+'.java') for n in names]])
expected={'String':'c412caea1d48baade8aa9d2653c6a23bb319a49deefe729ac99089f0c5248eba','System':'fd3898b354bb3e804fc09580d6a7c1d01ea02db4789ca2a876deb3ef9e03ae44','Class':'8986691ab80193f6958d7560a09f44b9dbacb22a30b317b905c811a2bf440ff7','Number':'fe77f74edbcc2777f4edfa6227759fd8a3b856838113fb0fe9880affc4c9876f','NumberFormatException':'a627a1649de875297f522fd2fde19f32b3e79f1945e7343941c696692e039d15','Integer':'bc07a956ca5c0739fc6a476c53755b4b3658caf3496e00b912b44e9aa52e4537'};imgs={n:(out/'bootstrap-classes/java/lang'/(n+'.class')).read_bytes() for n in names};assert {n:hashlib.sha256(b).hexdigest() for n,b in imgs.items()}==expected
s=(cand/'engine/MCEntryInterpreter.sol').read_text();assert s.count('MC-CLASSCOUNT25-PREFLIGHT1')==9 and 'MAX_RAW_CLASSES = 25' in s and 'uint32(25), uint32(262144)' in s and 'MAX_RAW_BYTES = 262144;' in s and 'new bytes32[](71)' in s and 'new uint256[](14)' in s
for n,b in imgs.items():m=re.search(r'function _bootstrap'+n+r'\(\).*?hex"([0-9a-f]+)";',s,re.S);assert m and bytes.fromhex(m.group(1))==b,n
s=s.replace('MC-CLASSCOUNT25-PREFLIGHT1','MC-CLASSCOUNT25-PARENT1');engine=out/'engine';shutil.copytree(cand/'engine',engine);(engine/'MCEntryInterpreter.sol').write_text(s);run('engine-build',['node',engine/'build.js']);ea=json.loads((engine/'MCEntryInterpreter.json').read_text());size=len(ea['deployedBytecode'])//2;assert size==370032 and size<=393216
co=out/'coordinator';shutil.copytree(cand/'coordinator',co);p=co/'MCEntryCoordinator.sol';x=p.read_text();assert x.count('MC-CLASSCOUNT25-PREFLIGHT1')==3 and x.count('[25]')==4 and 'n > 25' in x;x=x.replace('MC-CLASSCOUNT25-PREFLIGHT1','MC-CLASSCOUNT25-PARENT1');x,n=re.subn(r'address private constant ENGINE = .*?;', 'address private constant ENGINE = address(bytes20(hex"4d432d434f554e5432352d504152454e54000001"));',x);assert n==1;x,n=re.subn(r'bytes32 private constant ENGINE_CODEHASH = hex"[0-9a-f]{64}";', 'bytes32 private constant ENGINE_CODEHASH = hex"'+ea['codeHashes']['runtimeKeccak256']+'";',x);assert n==1;p.write_text(x);run('coordinator-build',['node',co/'build.js']);ca=json.loads((co/'MCEntryCoordinator.json').read_text())
wp=json.loads((cand/'pins.json').read_text());d=(cand/'tools/Go.txt').read_text()
for a,b in [('MC-CLASSCOUNT25-PREFLIGHT1','MC-CLASSCOUNT25-PARENT1'),(wp['engine']['runtimeSHA256'],ea['codeHashes']['runtimeSHA256']),('0x'+wp['engine']['runtimeKeccak256'],'0x'+ea['codeHashes']['runtimeKeccak256']),('0x'+wp['coordinator']['runtimeKeccak256'],'0x'+ca['codeHashes']['runtimeKeccak256']),(str(wp['engine']['bytes']),str(size)),(wp['address'],'0x4d432d434f554e5432352d504152454e54000001'),(wp['owner'],'0x4d432d434f554e5432352d4f574e455200000002')]:assert a in d,a;d=d.replace(a,b)
assert d.count('> 25')==2;(out/'main.go').write_text(d)
for label,args in (('gofmt',['gofmt','-w',out/'main.go']),('go-build',['go','build','-trimpath','-o',out/'driver',out/'main.go']),('go-vet',['go','vet',out/'main.go'])):run(label,args)
result={'basis':'feca8b5d2','worker':'cff7a63e0','domain':'MC-CLASSCOUNT25-PARENT1','address':'0x4d432d434f554e5432352d504152454e54000001','owner':'0x4d432d434f554e5432352d4f574e455200000002','runtimeCap':393216,'accepted320Unchanged':True,'acceptedPrior24Unchanged':True,'engine':{'bytes':size,**ea['codeHashes']},'coordinator':{'bytes':len(ca['deployedBytecode'])//2,**ca['codeHashes']},'bootstrapSHA256':expected,'bootstrapCount':71,'globalNativeBindings':10,'stringLocalBinding':10,'exceptionKinds':14,'externalLocalGas':1000000000,'resourceLookupGas':1000000,'reserve':25000000,'maxFrames':128,'rawLimits':[25,262144]};(out/'pins.json').write_text(json.dumps(result,indent=2)+'\n');print(json.dumps(result,indent=2))
